#include "nucleo_l476rg.hpp"
#include "stm32l4xx_ll_dma.h"

/**
 * @brief Handles interrupts generated by EXTI lines 10 through 15.
 *
 * Forwards the interrupt to the NUCLEO-L476RG user-button EXTI handler.
 */
extern "C" void EXTI15_10_IRQHandler(void) {
    platform::nucleo_l476rg::detail::
        handle_user_button_exti();
}

extern "C" void DMA1_Channel7_IRQHandler() {
    if (LL_DMA_IsActiveFlag_TC7(DMA1) != 0U) {
        LL_DMA_ClearFlag_TC7(DMA1);
        platform::nucleo_l476rg::detail::handle_console_transmit_dma_complete();
    }

    if (LL_DMA_IsActiveFlag_TE7(DMA1) != 0U) {
        LL_DMA_ClearFlag_TE7(DMA1);
        platform::nucleo_l476rg::detail::handle_console_transmit_dma_error();
    }
}